import { nim } from './nim'

export async function getGUID() {
  const guid = await nim.variableGet("getGUID");

  if (
    guid == null ||
    (typeof guid === "string" && guid.trim().length === 0) ||
    (Array.isArray(guid) && guid.length === 0)
  ) {
    throw new Error("GUID was not found or is empty.");
  }

  return {
    GUID: guid
  };
}

